/** An input that is gone after the process. */
export const USING_UP_ACTIONS: readonly string[] = ["consume"];
/** An input that takes a stock off hand (used up, combined, picked up, accepted). */
export const CONSUMING_ACTIONS: readonly string[] = ["consume", "pickup", "accept", "combine"];
/** An act that occupies a means for a while. */
export const OCCUPYING_ACTIONS: readonly string[] = ["use"];
/** An act that IS labour. */
export const LABOUR_ACTIONS: readonly string[] = ["work"];
/** An act that carries effort: labour, or a means occupied for hours. */
export const EFFORT_ACTIONS: readonly string[] = ["use", "work"];
/** An act that moves a thing from one place to another. */
export const RELOCATING_ACTIONS: readonly string[] = ["pickup", "dropoff"];
/** What a process makes: an output that puts a quantity on hand, less the relocations. */
