/** A flow into a process. */
export const isInput = (a: string | null | undefined): boolean => !!a && INPUT_ACTIONS.includes(a);
/** A flow out of a process. */
export const isOutput = (a: string | null | undefined): boolean => !!a && OUTPUT_ACTIONS.includes(a);
/** An input gone after the process. */
export const isUsingUp = (a: string | null | undefined): boolean => !!a && USING_UP_ACTIONS.includes(a);
/** A means occupied. */
export const isOccupying = (a: string | null | undefined): boolean => !!a && OCCUPYING_ACTIONS.includes(a);
/** Labour. */
export const isLabour = (a: string | null | undefined): boolean => !!a && LABOUR_ACTIONS.includes(a);
/** A relocation. */
export const isRelocating = (a: string | null | undefined): boolean => !!a && RELOCATING_ACTIONS.includes(a);
/** What a process makes. */
export const isMaking = (a: string | null | undefined): boolean => !!a && MAKING_ACTIONS.includes(a);
/** What comes newly into being. */
export const isCreating = (a: string | null | undefined): boolean => !!a && CREATING_ACTIONS.includes(a);
/** A count's adjustment. */
export const isAdjustment = (a: string | null | undefined): boolean => !!a && ADJUSTMENT_ACTIONS.includes(a);

